<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/session.php'; require_once __DIR__ . '/includes/helpers.php'; require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/booking.php';
require_login(); $booking = $_SESSION['booking'] ?? []; if (empty($booking['resource_id']) || empty($booking['booking_date']) || empty($booking['start_times'])) redirect('booking-step-1.php'); $statement = db()->prepare('SELECT * FROM resources WHERE id = ? AND is_active = 1'); $statement->execute([(int) $booking['resource_id']]); $resource = $statement->fetch(); if (!$resource) redirect('booking-step-1.php'); $calculation = calculate_slot_bookings($resource, $booking['start_times'], (array) ($booking['extra_ids_by_slot'] ?? []), (string) ($booking['coupon_code'] ?? ''));
$error = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $occupied = occupied_slots((int) $resource['id'], $booking['booking_date']); if (!valid_date($booking['booking_date']) || array_intersect($booking['start_times'], $occupied)) { $error = 'Mindestens einer der ausgewählten Slots wurde gerade vergeben. Bitte starten Sie die Buchung erneut.'; } else { try { $pdo = db(); $pdo->beginTransaction(); $insert = $pdo->prepare('INSERT INTO bookings (user_id, resource_id, booking_date, start_time, end_time, subtotal, discount_amount, total_price, coupon_code) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)'); $extra_insert = $pdo->prepare('INSERT INTO booking_extras (booking_id, extra_id, quantity, unit_price) VALUES (?, ?, 1, ?)'); foreach ($calculation['slots'] as $index => $slot) { $is_first = $index === 0; $slot_discount = $is_first ? $calculation['discount'] : 0; $slot_total = $slot['subtotal'] - $slot_discount; $insert->execute([(int) current_user()['id'], (int) $resource['id'], $booking['booking_date'], $slot['start_time'], slot_options()[$slot['start_time']], $slot['subtotal'], $slot_discount, $slot_total, $is_first ? ($calculation['coupon']['code'] ?? null) : null]); $booking_id = (int) $pdo->lastInsertId(); foreach ($slot['extras'] as $extra) $extra_insert->execute([$booking_id, (int) $extra['id'], $extra['price']]); } $pdo->commit(); unset($_SESSION['booking']); flash('success', 'Ihre Buchung wurde verbindlich gespeichert.'); redirect('my-bookings.php'); } catch (PDOException $exception) { if ($pdo->inTransaction()) $pdo->rollBack(); $error = ((int) ($exception->errorInfo[1] ?? 0) === 1062) ? 'Mindestens einer der ausgewählten Slots wurde gerade vergeben. Bitte starten Sie die Buchung erneut.' : 'Die Buchung konnte nicht gespeichert werden.'; } } }
$page_title = 'Buchung bestätigen'; require __DIR__ . '/includes/header.php';
?><p class="step-indicator">Schritt 4 von 4</p><h1>Buchung zusammenfassen</h1><?php if ($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="summary-panel"><dl class="row"><dt class="col-sm-4">Sportanlage</dt><dd class="col-sm-8"><?= e($resource['name']) ?></dd><dt class="col-sm-4">Datum</dt><dd class="col-sm-8"><?php foreach ($calculation['slots'] as $slot): ?><div class="mb-2"><strong><?= e($slot['start_time']) ?> bis <?= e(slot_options()[$slot['start_time']]) ?></strong><br><span class="small">Extras: <?= $slot['extras'] ? implode(', ', array_map(static fn (array $extra): string => e($extra['name']), $slot['extras'])) : 'Keine' ?></span></div><?php endforeach; ?></dd><dt class="col-sm-4">Zwischensumme</dt><dd class="col-sm-8"><?= euro($calculation['subtotal']) ?></dd><dt class="col-sm-4">Rabatt</dt><dd class="col-sm-8">- <?= euro($calculation['discount']) ?></dd><dt class="col-sm-4 fw-bold">Gesamtpreis</dt><dd class="col-sm-8 fw-bold"><?= euro($calculation['total']) ?></dd></dl><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button class="btn btn-primary" type="submit">Jetzt verbindlich buchen</button></form></div>
<?php require __DIR__ . '/includes/footer.php';